import itertools, json

bands = "UVWXYZ"

def base(p):
    # p maps band -> slot (1..6)
    return p['V'] < p['Z'] and p['U'] >= 4 and p['Y'] <= 3

def orig(p):
    return p['W'] < p['X'] and p['Z'] < p['X']

options = {
    'A': lambda p: all(p[b] < p['X'] for b in "VWYZ"),  # only Uneasy can be later than Xpert
    'B': lambda p: p['V'] < p['W'] < p['Z'],
    'C': lambda p: p['V'] < p['X'] and p['W'] < p['X'],
    'D': lambda p: abs(p['X'] - p['U']) == 1,
    'E': lambda p: p['X'] in (5, 6),
}

perms = []
for perm in itertools.permutations(range(1, 7)):
    perms.append(dict(zip(bands, perm)))

orig_set = {tuple(p[b] for b in bands) for p in perms if base(p) and orig(p)}

result = {}
matches = []
for k, f in options.items():
    s = {tuple(p[b] for b in bands) for p in perms if base(p) and f(p)}
    same = (s == orig_set)
    result[k] = {"count": len(s), "same": same}
    if same:
        matches.append(k)

if len(matches) == 1:
    final = matches[0]
else:
    final = "UNSUPPORTED"

print(json.dumps({
    "final_answer": final,
    "evidence": {"original_count": len(orig_set), "options": result}
}))
